window.docContents[113].resolve({"/rules/PL1001/#PL1001-limitations":{"contents":"The editor linter reports this rule for completed declarations of the current file (editorSnapshot); a clean editor buffer is not a project result.\n\nA metaprogram that adds declarations still produces owned constants; they are inspected like authored ones.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1001: Project logical axioms are forbidden","header":"Limitations and unsupported cases","id":"/rules/PL1001/#PL1001-limitations"}});